% =========================================================================
% Fig. 2: Kurtosis-adaptive constellation family
%
% Plots the geometrically and probabilistically shaped constellations
% (M = 64) generated by the pretrained adaptive constellation family for
% target kurtosis values between 1 and 2. The color indicates the target
% kurtosis, the marker size the probability of each constellation point.
%
% Reference:
% [1] B. Geiger, L. Hampel, and L. Schmalen, "Joint power and
%     adaptive-constellation optimization for OFDM-ISAC systems," in Proc.
%     IEEE Conf. Integr. Sens. Commun. (ISAC), Lisbon, Portugal, Nov. 2026.
%     arXiv:2611.12166
%
% License: MIT (see LICENSE in repository root)
% =========================================================================

clear; close all; clc;

kappa_target = 1:0.01:2;                    % target kurtosis values
matlab_dir = fileparts(fileparts(mfilename("fullpath")));   % .../matlab
addpath(matlab_dir, fullfile(matlab_dir, "functions"));
weights = load(fullfile(matlab_dir, "adaptive_constellation_weights.mat"));
M = weights.M;

% Generate all constellations
x = zeros(M, numel(kappa_target));
p = zeros(M, numel(kappa_target));
for k = 1:numel(kappa_target)
    [x(:, k), p(:, k)] = generate_adaptive_constellation(kappa_target(k), weights);
end

% Plot: marker area proportional to the probability (sqrt -> radius as in [1])
kappa_grid = repmat(kappa_target, M, 1);
marker_size = (0.5 + 25*sqrt(p(:))).^2;

figure("Name", "Fig. 2: Adaptive constellation");
scatter(real(x(:)), imag(x(:)), marker_size, kappa_grid(:), "filled");
axis equal; grid on; box on;
xlim([-2.5, 2.5]); ylim([-2.5, 2.5]);
xlabel("Re\{x_n\}"); ylabel("Im\{x_n\}");
colormap(flipud(spectral_colormap()));
clim([1, 2]);
cb = colorbar;
cb.Label.Interpreter = "latex";
cb.Label.String = "Target kurtosis $\tilde{\kappa}_n$";
title(sprintf("Adaptive constellation, M = %d", M));


function cmap = spectral_colormap()
% Diverging "Spectral" colormap (ColorBrewer), red -> yellow -> blue
anchors = [213 62 79; 244 109 67; 253 174 97; 254 224 139; 255 255 191;
           230 245 152; 171 221 164; 102 194 165; 50 136 189] / 255;
cmap = interp1(linspace(0, 1, size(anchors, 1)), anchors, linspace(0, 1, 256));
end
